"""Translations keyed by the English source text."""
LANGUAGES = {"en": "English", "it": "Italiano", "es": "Español", "fr": "Français"}
_language = "en"


def set_language(code):
    global _language
    _language = code if code in LANGUAGES else "en"


def language():
    return _language


def tr(message, *args):
    if _language != "en":
        message = MESSAGES.get(message, {}).get(_language, message)
    return message.format(*args) if args else message


